const numeros = [1, 2, 3, 4, 5, 6];

const total = numeros
  .filter((numero) => numero % 2 === 0)
  .map((numero) => numero * 10)
  .reduce((acc, numero) => acc + numero, 0);

console.log(total); // 120

const ventas = [
  { tipo: 'libro', total: 10 },
  { tipo: 'curso', total: 30 },
  { tipo: 'libro', total: 15 },
];

const totales = ventas.reduce((acc, venta) => {
  const tipo = venta.tipo;
  acc[tipo] = (acc[tipo] || 0) + venta.total;
  return acc;
}, {});

console.log(totales);
// { libro: 25, curso: 30 }

const categorias = ['js', 'react', 'js', 'css', 'js'];

const frecuencias = categorias.reduce((acc, categoria) => {
  acc[categoria] = (acc[categoria] || 0) + 1;
  return acc;
}, {});

console.log(frecuencias);
// { js: 3, react: 1, css: 1 }

const pedidos = [
  { categoria: 'libros', total: 20 },
  { categoria: 'cursos', total: 50 },
  { categoria: 'libros', total: 30 },
];

const grupos = pedidos.reduce((acc, pedido) => {
  const key = pedido.categoria;

  const actual = acc[key] || {
    cantidad: 0,
    total: 0,
  };

  acc[key] = {
    cantidad: actual.cantidad + 1,
    total: actual.total + pedido.total,
  };

  return acc;
}, {});

console.log(grupos.libros);
// { cantidad: 2, total: 50 }

const precios = [10, 25, 15];

const resumen = precios.reduce(
  (acc, precio) => ({
    total: acc.total + precio,
    cantidad: acc.cantidad + 1,
  }),
  {
    total: 0,
    cantidad: 0,
  },
);

console.log(resumen);
// { total: 50, cantidad: 3 }

const pedidos = [
  { categoria: 'libro', total: 20, pagado: true },
  { categoria: 'curso', total: 40, pagado: false },
  { categoria: 'libro', total: 30, pagado: true },
];

const resumen = pedidos
  .filter((pedido) => pedido.pagado)
  .map((pedido) => ({
    ...pedido,
    total: pedido.total * 2,
  }))
  .reduce((acc, pedido) => {
    const key = pedido.categoria;
    acc[key] = (acc[key] || 0) + pedido.total;
    return acc;
  }, {});

console.log(resumen);
// { libro: 100 }
